            values.push({value, value});
        } else {
            int currentMinimum = min(value, values.top().second);
            values.push({value, currentMinimum});
        }
    }

    void pop() {
        if (!values.empty()) {
            values.pop();
        }
    }

    int top() {
        return values.top().first;
    }

    int getMin() {
        return values.top().second;
    }
